create or replace function einvoice.get_issuance_profile(
  p_tenant_id uuid,
  p_actor_id uuid
) returns table(
  profile_version int,
  template_id text,
  signing_config_id text,
  signing_method text,
  compatibility_warnings jsonb
)
language plpgsql
security definer
set search_path = einvoice, iam, public
as $$
begin
  if auth.uid() is null
     or p_actor_id is null
     or p_actor_id <> auth.uid()
     or not iam.has_permission(p_tenant_id, 'einvoice.manage_configuration') then
    raise exception 'NO_PERMISSION: einvoice.manage_configuration required';
  end if;

  return query
  select
    ts.profile_version,
    ts.default_template_id,
    case
      when ts.default_invoice_series is null then null
      when substr(ts.default_invoice_series, 5, 1) = 'M' then 'sign-nosign'
      else 'sign-hsm'
    end,
    case
      when ts.default_invoice_series is null then null
      when substr(ts.default_invoice_series, 5, 1) = 'M' then 'noSign'
      else 'hsm'
    end,
    '[]'::jsonb
  from einvoice.tenant_settings ts
  where ts.tenant_id = p_tenant_id
  union all
  select 0, null::text, null::text, null::text, '[]'::jsonb
  where not exists (
    select 1 from einvoice.tenant_settings where tenant_id = p_tenant_id
  )
  limit 1;
end;
$$;

create or replace function einvoice.set_default_issuance_configuration(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_template_id text,
  p_signing_config_id text,
  p_expected_profile_version int default null
) returns table(
  profile_version int,
  template_id text,
  signing_config_id text,
  signing_method text,
  compatibility_warnings jsonb
)
language plpgsql
security definer
set search_path = einvoice, iam, public
as $$
declare
  v_version int;
  v_template jsonb;
  v_is_mtt boolean;
  v_method text;
  v_sign_type int;
  v_invoice_series varchar(100);
begin
  if auth.uid() is null
     or p_actor_id is null
     or p_actor_id <> auth.uid()
     or not iam.has_permission(p_tenant_id, 'einvoice.manage_configuration') then
    raise exception 'NO_PERMISSION: einvoice.manage_configuration required';
  end if;

  select elem
  into v_template
  from einvoice.provider_connections pc,
       jsonb_array_elements(coalesce(pc.capabilities_snapshot -> 'templates', '[]'::jsonb)) as elem
  where pc.tenant_id = p_tenant_id
    and pc.status = 'CONNECTED'
    and (elem ->> 'template_id' = p_template_id or elem ->> 'templateId' = p_template_id)
  limit 1;

  if v_template is null then
    raise exception 'TEMPLATE_NOT_AVAILABLE: configured template is not in provider capability';
  end if;

  v_is_mtt := coalesce(
    (v_template ->> 'is_mtt')::boolean,
    upper(substr(coalesce(v_template ->> 'invoice_series', v_template ->> 'symbol', ''), 5, 1)) = 'M'
  );

  if p_signing_config_id in ('sign-nosign', 'sign-mtt') then
    v_method := 'noSign';
    v_sign_type := 5;
  elsif p_signing_config_id = 'sign-hsm' then
    v_method := 'hsm';
    v_sign_type := 2;
  else
    raise exception 'SIGNING_CONFIGURATION_NOT_AVAILABLE: unsupported signing configuration';
  end if;

  if v_is_mtt and v_sign_type is distinct from 5 then
    raise exception 'SIGNING_CONFIGURATION_NOT_AVAILABLE: MTT template requires SignType=5';
  end if;

  if (not v_is_mtt) and v_sign_type is distinct from 2 then
    raise exception 'SIGNING_CONFIGURATION_NOT_AVAILABLE: non-MTT template requires SignType=2';
  end if;

  v_invoice_series := coalesce(
    nullif(btrim(v_template ->> 'invoice_series'), ''),
    nullif(btrim(v_template ->> 'symbol'), '')
  );

  if v_invoice_series is null then
    raise exception 'TEMPLATE_NOT_AVAILABLE: template has no invoice series';
  end if;

  insert into einvoice.tenant_settings as ts (
    tenant_id, default_template_id, default_invoice_series, profile_version
  )
  values (
    p_tenant_id,
    coalesce(v_template ->> 'template_id', p_template_id),
    v_invoice_series,
    1
  )
  on conflict (tenant_id) do update set
    default_template_id = excluded.default_template_id,
    default_invoice_series = excluded.default_invoice_series,
    profile_version = ts.profile_version + 1,
    updated_at = now()
  where p_expected_profile_version is null
     or ts.profile_version = p_expected_profile_version
  returning ts.profile_version into v_version;

  if v_version is null then
    raise exception 'STATE_CHANGED: profile version mismatch';
  end if;

  return query
  select v_version, p_template_id, p_signing_config_id, v_method, '[]'::jsonb;
end;
$$;

create or replace function einvoice.get_automation_policy(
  p_tenant_id uuid,
  p_actor_id uuid
) returns table(
  auto_issue_enabled boolean,
  auto_send_enabled boolean,
  policy_version int,
  blockers jsonb
)
language plpgsql
security definer
set search_path = einvoice, iam, public
as $$
begin
  if auth.uid() is null
     or p_actor_id is null
     or p_actor_id <> auth.uid()
     or not iam.has_permission(p_tenant_id, 'einvoice.manage_configuration') then
    raise exception 'NO_PERMISSION: einvoice.manage_configuration required';
  end if;

  return query
  select
    coalesce(ts.auto_issue_enabled, false),
    coalesce(ts.auto_send_enabled, false),
    coalesce(ts.policy_version, 0),
    '[]'::jsonb
  from einvoice.tenant_settings ts
  where ts.tenant_id = p_tenant_id
  union all
  select false, false, 0, '[]'::jsonb
  where not exists (
    select 1 from einvoice.tenant_settings where tenant_id = p_tenant_id
  )
  limit 1;
end;
$$;

create or replace function einvoice.update_automation_policy(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_auto_issue_enabled boolean default null,
  p_auto_send_enabled boolean default null,
  p_expected_policy_version int default 0
) returns table(
  auto_issue_enabled boolean,
  auto_send_enabled boolean,
  policy_version int,
  blockers jsonb
)
language plpgsql
security definer
set search_path = einvoice, iam, public
as $$
declare
  v_version int;
  v_auto_issue_enabled boolean;
  v_auto_send_enabled boolean;
begin
  if auth.uid() is null
     or p_actor_id is null
     or p_actor_id <> auth.uid()
     or not iam.has_permission(p_tenant_id, 'einvoice.manage_configuration') then
    raise exception 'NO_PERMISSION: einvoice.manage_configuration required';
  end if;

  -- KI-02: chỉ chặn khi BẬT MỚI (đang tắt / chưa có dòng, gửi true) mà tổ chức
  -- chưa sẵn sàng (BR-10). Đang bật sẵn thì vẫn lưu được; tắt luôn được.
  if coalesce(p_auto_issue_enabled, false)
     and not coalesce((select ts.auto_issue_enabled from einvoice.tenant_settings ts
                       where ts.tenant_id = p_tenant_id), false)
     and not (
       exists (select 1 from einvoice.provider_connections pc
               where pc.tenant_id = p_tenant_id and pc.status = 'CONNECTED')
       and exists (select 1 from einvoice.tenant_settings ts
                   where ts.tenant_id = p_tenant_id and ts.default_template_id is not null)
     ) then
    raise exception 'CONFIG_NOT_READY: automation requires a connected provider and a default template';
  end if;

  insert into einvoice.tenant_settings as ts (
    tenant_id, auto_issue_enabled, auto_send_enabled, policy_version
  ) values (
    p_tenant_id,
    coalesce(p_auto_issue_enabled, false),
    coalesce(p_auto_send_enabled, false),
    1
  )
  on conflict (tenant_id) do update set
    auto_issue_enabled = coalesce(p_auto_issue_enabled, ts.auto_issue_enabled),
    auto_send_enabled = coalesce(p_auto_send_enabled, ts.auto_send_enabled),
    policy_version = ts.policy_version + 1,
    updated_at = now()
  where ts.policy_version = p_expected_policy_version
  returning ts.policy_version,
            ts.auto_issue_enabled,
            ts.auto_send_enabled
  into v_version, v_auto_issue_enabled, v_auto_send_enabled;

  if v_version is null then
    raise exception 'STATE_CHANGED: policy version mismatch';
  end if;

  return query
  select v_auto_issue_enabled, v_auto_send_enabled, v_version, '[]'::jsonb;
end;
$$;

create or replace function einvoice.get_configuration_readiness(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_purpose text default null
) returns table(level text, blockers jsonb, warnings jsonb)
language plpgsql
security definer
set search_path = einvoice, iam, public
as $$
begin
  if auth.uid() is null
     or p_actor_id is null
     or p_actor_id <> auth.uid()
     or not iam.has_permission(p_tenant_id, 'einvoice.manage_configuration') then
    raise exception 'NO_PERMISSION: einvoice.manage_configuration required';
  end if;

  return query
  select
    case
      when pc.status is distinct from 'CONNECTED' then 'notReady'
      when ts.default_template_id is null then 'notReady'
      else 'ready'
    end,
    case
      when pc.status is distinct from 'CONNECTED'
        then jsonb_build_array(jsonb_build_object('code','provider_not_connected','message','Not connected'))
      when ts.default_template_id is null
        then jsonb_build_array(jsonb_build_object('code','template_unavailable','message','No default template'))
      else '[]'::jsonb
    end,
    '[]'::jsonb
  from (select 1) s
  left join einvoice.provider_connections pc
    on pc.tenant_id = p_tenant_id and pc.status <> 'DISCONNECTED'
  left join einvoice.tenant_settings ts on ts.tenant_id = p_tenant_id;
end;
$$;

create or replace function einvoice.list_provider_templates(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_invoice_with_code boolean default null,
  p_year int default null
) returns table(
  template_id text,
  name text,
  serial text,
  symbol text,
  invoice_series text,
  invoice_with_code boolean,
  is_mtt boolean,
  is_send_summary boolean
)
language plpgsql
security definer
set search_path = einvoice, iam, public
as $$
declare
  v_connection record;
  v_templates jsonb;
begin
  if auth.uid() is null
     or p_actor_id is null
     or p_actor_id <> auth.uid()
     or not iam.has_permission(p_tenant_id, 'einvoice.manage_configuration') then
    raise exception 'NO_PERMISSION: einvoice.manage_configuration required';
  end if;

  select pc.id, pc.status, pc.capabilities_snapshot
  into v_connection
  from einvoice.provider_connections pc
  where pc.tenant_id = p_tenant_id and pc.status = 'CONNECTED'
  limit 1;

  if v_connection.id is null then
    raise exception 'PROVIDER_NOT_CONNECTED';
  end if;

  v_templates := v_connection.capabilities_snapshot -> 'templates';

  if v_templates is not null and jsonb_array_length(v_templates) > 0 then
    return query
    select
      elem ->> 'template_id' as template_id,
      elem ->> 'name' as name,
      elem ->> 'serial' as serial,
      coalesce(elem ->> 'invoice_series', elem ->> 'symbol') as symbol,
      coalesce(elem ->> 'invoice_series', elem ->> 'symbol') as invoice_series,
      case
        when elem ? 'invoice_with_code' then (elem ->> 'invoice_with_code')::boolean
        else null
      end as invoice_with_code,
      coalesce((elem ->> 'is_mtt')::boolean, false) as is_mtt,
      coalesce((elem ->> 'is_send_summary')::boolean, false) as is_send_summary
    from jsonb_array_elements(v_templates) as elem
    where coalesce((elem ->> 'is_available')::boolean, true) = true
      and (
        p_invoice_with_code is null
        or (
          case
            when elem ? 'invoice_with_code' then (elem ->> 'invoice_with_code')::boolean
            else null
          end
        ) is not distinct from p_invoice_with_code
      );
  end if;
end;
$$;

